//! ⚡️ Complete building energy subject and actual declaration-owned SQLite I/O laws.
use crate::standards::v1::subsets::any::io::sqlite::snapshot::Din18599Snapshot;
#[test]
fn sqlite_snapshot_din18599_owned_native_decoder_controls_both_physical_payloads(){
 use store::io::IoPayload;
 let snapshot=fixture();let limits=SqliteDatabaseLimits::default();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(store::ArtifactPack::encode_pack(&snapshot)),SnapshotEncoding::Text=>IoPayload::Text(store::ArtifactDsl::print_dsl(&snapshot))};
  let restored=Din18599Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored,snapshot);
  assert!(Din18599Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());
  assert!(Din18599Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:1,..limits})).is_err());
  assert!(Din18599Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1,..limits})).is_err());
 }
}
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{export_sqlite_database,import_sqlite_database,SnapshotEncoding,SqliteDatabase,SqliteDatabaseLimits,SqliteSnapshotControl,SqliteSnapshotPhase,SqliteValue}};

fn fixture()->Din18599Snapshot{semio_framework_pack_json::from_json_str(include_str!("../🧫️fixtures/🔣️.json"), semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn database(snapshot:&Din18599Snapshot)->SqliteDatabase{snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn roundtrip(snapshot:&Din18599Snapshot)->Din18599Snapshot{let bytes=export_sqlite_database(&database(snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();Din18599Snapshot::from_sqlite_database(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn set_every_word(s:&mut Din18599Snapshot,v:f64){s.net_floor_area_m2=v;s.heated_volume_m3=v;s.geg_qp_factor=v;s.delta_u_wb_w_m2k=v;for z in &mut s.zones{z.area_m2=v;z.volume_m3=v;z.theta_i_heat_c=v;z.theta_i_cool_c=v;z.internal_gains_w_m2=v;z.lighting_power_w_m2=v;}for e in &mut s.elements{e.area_m2=v;e.u_value_w_m2k=v;e.orientation_deg=v;e.tilt_deg=v;e.g_value=v;e.fc=v;}s.heating.generation_efficiency=v;s.heating.distribution_efficiency=v;s.heating.storage_efficiency=v;s.heating.transfer_efficiency=v;s.dhw.specific_demand_kwh_person_a=v;s.dhw.storage_loss_kwh_a=v;s.dhw.distribution_loss_kwh_a=v;s.ventilation.airflow_m3_h=v;s.ventilation.heat_recovery_eta=v;s.ventilation.fan_power_w=v;if let Some(p)=&mut s.cooling.plant{p.eer=v;}s.lighting.control_factor=v;s.renewables.pv_area_m2=v;s.renewables.pv_efficiency=v;s.renewables.solar_thermal_kwh_a=v;s.climate.theta_e_c=[v;12];s.climate.g_h_w_m2=[v;12];}

