#[test]
fn sqlite_snapshot_din18599_independent_sqlite_joins_climate_identity_and_plant_edits(){
    use std::{io::Write,process::{Command,Stdio}};
    let mut expected=fixture();let bytes=export_sqlite_database(&database(&expected),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
    let script="import{Database}from'bun:sqlite';import{Buffer}from'node:buffer';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const rows=db.query('SELECT e.ordinal AS element,z.ordinal AS zone,e.u_value_w_m2k FROM din18599_element e JOIN din18599_zone z ON z.logical_id=e.zone_logical_id WHERE e.id=1 ORDER BY z.ordinal').all();if(rows.length!==2||rows[0].zone!==0||rows[1].zone!==1||rows[0].u_value_w_m2k!==1.125)throw Error('ordered ambiguous logical relationship');if(db.query('SELECT zone_logical_id FROM din18599_element WHERE id=2').get().zone_logical_id!=='missing zone')throw Error('unresolved logical reference');const c=db.query('SELECT artifact_id,artifact_kind,standard,subset FROM din18599_climate_child').get();if(c.artifact_id!=='climate-document'||c.artifact_kind!=='s.stdio.semio'||c.standard!=='table'||c.subset!=='*')throw Error('climate child identity');const b=Buffer.alloc(8);b.writeDoubleBE(0.75);db.run(\"UPDATE din18599_heating SET generation_efficiency=0.75,generation_efficiency_ieee754_bits=?,generation_efficiency_ieee754_class='finite',energy_carrier='Geändert 世界'\",[BigInt.asIntN(64,b.readBigUInt64BE())]);db.run(\"UPDATE din18599_zone SET occupants=4294967294 WHERE id=1\");db.run(\"UPDATE din18599_climate_child SET artifact_id='changed-climate',subset='changed-subset'\");db.run('DELETE FROM din18599_cooling_plant');await Bun.write(Bun.stdout,db.serialize());db.close();";
    let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));expected.heating.generation_efficiency=0.75;expected.heating.energy_carrier="Geändert 世界".into();expected.zones[0].occupants=4294967294;expected.climate_table.target.artifact_id="changed-climate".into();expected.climate_table.target.dialect.subset="changed-subset".into();expected.cooling.plant=None;assert_eq!(Din18599Snapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);
}

#[test]
fn sqlite_snapshot_din18599_refuses_malformed_choices_widths_parents_ordinals_and_word_companions(){let database=database(&fixture());for(table,index,column,value)in[("din18599_document",0,1,SqliteValue::Text("unknown".into())),("din18599_zone",0,11,SqliteValue::Integer(4294967296)),("din18599_zone",0,6,SqliteValue::Text("unknown".into())),("din18599_element",0,6,SqliteValue::Text("unknown".into())),("din18599_element",0,14,SqliteValue::Text("unknown".into())),("din18599_zone",1,2,SqliteValue::Integer(0)),("din18599_element",0,2,SqliteValue::Integer(99)),("din18599_document",0,11,SqliteValue::Text("nan".into())),("din18599_climate_month",0,0,SqliteValue::Integer(13)),("din18599_climate_month",11,5,SqliteValue::Text("nan".into()))]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows[index].values[column]=value;assert!(Din18599Snapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{table}");}for name in["climate_child","climate_month","zone","element","heating","dhw","ventilation","cooling","cooling_plant","lighting","renewables"]{let mut invalid=database.clone();invalid.table_mut(&format!("din18599_{name}")).unwrap().rows[0].values[1]=SqliteValue::Integer(99);assert!(Din18599Snapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{name}");}for name in["document","climate_child","climate_month","heating","dhw","ventilation","cooling","lighting","renewables"]{let mut invalid=database.clone();invalid.table_mut(&format!("din18599_{name}")).unwrap().rows.clear();assert!(Din18599Snapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{name}");}}

#[test]
fn sqlite_snapshot_din18599_initial_and_nested_operations_support_cancellation_and_native_admission(){
    let mut snapshot=fixture();assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:1,..SqliteDatabaseLimits::default()})).is_err());assert!(Din18599Snapshot::from_sqlite_database(&database(&snapshot),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:0,..SqliteDatabaseLimits::default()})).is_err());
    for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1024,..SqliteDatabaseLimits::default()})).unwrap_err().to_string().contains("native encoding exceeds file byte limit"));}
    let controls:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🎛️control.json")).unwrap();snapshot.zones=vec![snapshot.zones[0].clone();controls["entityCount"].as_u64().unwrap()as usize];let cancel_at=controls["cancelAt"].as_u64().unwrap()as usize;for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut reached=false;assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut|event|{if event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>=cancel_at{reached=true;false}else{true}},SqliteDatabaseLimits::default())).is_err());assert!(reached);}let large=database(&snapshot);for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot]{let mut reached=false;let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==phase&&event.completed>=cancel_at{reached=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(if phase==SqliteSnapshotPhase::ProjectSnapshot{snapshot.to_sqlite_database(&mut control).is_err()}else{Din18599Snapshot::from_sqlite_database(&large,&mut control).is_err()});assert!(reached);}
}

#[test]
fn sqlite_snapshot_din18599_large_child_identity_cancels_before_any_encoding_or_semantic_copy(){let mut snapshot=fixture();snapshot.climate_table.child_id="x".repeat(131073);let database=database(&snapshot);for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot,SqliteSnapshotPhase::EncodeNative]{let mut reached=false;let mut callback=|event:store::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==phase&&event.total>=65536&&event.completed>=65536&&event.completed<event.total{reached=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());let rejected=match phase{SqliteSnapshotPhase::ProjectSnapshot=>snapshot.to_sqlite_database(&mut control).is_err(),SqliteSnapshotPhase::ReconstructSnapshot=>Din18599Snapshot::from_sqlite_database(&database,&mut control).is_err(),_=>snapshot.encode_sqlite_snapshot_native(SnapshotEncoding::Text,&mut control).is_err()};assert!(rejected);assert!(reached);}}


